def get_leaf_costs(parent, mult):
    res = {}
    children = [(c, d) for p, c, d in rules if p == parent]
    if not children:
        res[parent] = res.get(parent, 0) + mult
    else:
        for c, d in children:
            sub = get_leaf_costs(c, mult * d)
            for part, count in sub.items():
                res[part] = res.get(part, 0) + count
    return res

